  @override
  String get batchDlgHelpBody =>
      '1. Escolha uma predefinição ou ative regras; em seguida, copie as regras e ajuste a ordem conforme necessário.\n\n2. A pré-visualização mostra os nomes que serão usados. A pesquisa e os filtros afetam somente a exibição. Desmarcar um item o exclui e recalcula a numeração. Edite um nome individualmente ou restaure o resultado das regras.\n\n3. Resolva todos os problemas antes de executar. Sufixos automáticos tratam nomes duplicados sem sobrescrever arquivos. Renomeie pastas que trocarão de nome em lotes separados.\n\n4. Durante a execução, você pode interromper o processamento dos itens seguintes; o item atual será concluído primeiro. A página de resultados mostra as alterações concluídas e permite desfazê-las. Não é possível desfazer se a lista tiver sido alterada desde a execução.\n\nEsta operação altera somente nomes e caminhos de pastas; o conteúdo e as extensões dos arquivos permanecem iguais. Renomear uma pasta pai não impede que os filhos marcados sejam renomeados, e renomear a pasta pai também move seus filhos.';

