      'Quando ativada, esta página mostra o estado da otimização da bateria. Se o app não estiver na lista de exceções da bateria, você poderá abrir as configurações do sistema para adicioná-lo.\n\nA otimização de bateria do Android (Doze) limita apps em segundo plano. Adicionar este app à lista de exceções impede que o sistema o encerre para economizar energia.\n\nDesativar esta opção oculta somente o cartão de lembrete; não altera a exceção de bateria do app.';

