  }

  @override
  String get platformTutorialStepsHeading => 'Etapas de otimização';

  @override
  String get platformTutorialTipsHeading => 'Dica';

  @override
  String get platformTutorialTipsDescription =>
      'Depois de concluir estas configurações, volte à página “Otimização em segundo plano” e confira se o estado foi atualizado. Se o problema continuar, consulte o guia de outra plataforma ou relate o problema no GitHub.';

  @override
  String get platformTutorialAndroidStep1Title =>
      'Desativar a otimização da bateria';

  @override
  String get platformTutorialAndroidStep1Description =>
      'Abra Configurações → Apps → Stroom → Bateria e escolha “Sem restrições” ou “Não otimizar”. Você também pode tocar em “Ignorar otimização da bateria” na página “Otimização em segundo plano” deste app para adicionar o Stroom à lista de permissões do modo de economia de energia do sistema. Os caminhos variam conforme a marca do dispositivo.';

  @override
  String get platformTutorialAndroidStep2Title =>
      'Permitir atividade em segundo plano';

  @override
  String get platformTutorialAndroidStep2Description =>
      'Abra Configurações → Apps → Stroom e ative “Permitir atividade em segundo plano” e “Permitir início automático”. Alguns celulares também exigem que o início automático seja permitido na Central de segurança ou no Gerenciador do telefone.';

  @override
  String get platformTutorialAndroidStep3Title =>
      'Bloquear o processo em segundo plano';

  @override
  String get platformTutorialAndroidStep3Description =>
      'Na visualização de apps recentes, deslize para baixo no cartão do Stroom ou toque no ícone de cadeado para impedir que o sistema encerre o app.';

  @override
  String get platformTutorialAndroidStep4Title =>
      'Permitir notificações (Android 13 ou posterior)';

  @override
  String get platformTutorialAndroidStep4Description =>
      'O Android 13 e versões posteriores exigem permissão para notificações. Sem ela, a notificação em primeiro plano do serviço em segundo plano fica oculta, embora o serviço continue em execução. O app solicita a permissão quando você toca em “Iniciar serviço” pela primeira vez; você também pode ativá-la em Configurações → Apps → Stroom → Notificações.';

  @override
  String get platformTutorialAndroidStep5Title =>
      'Ignorar otimização da bateria';

  @override
  String get platformTutorialAndroidStep5Description =>
      'Quando você ativa “Notificações de conclusão de tarefas” no Stroom, o app solicita a permissão correspondente. Você também pode conferir se o Stroom está definido como “Não otimizar” em Configurações → Apps → Acesso especial a apps → Otimização da bateria.';

  @override
  String get platformTutorialAndroidStep6Title =>
      'Início automático e gerenciamento em segundo plano em dispositivos Android';

  @override
  String get platformTutorialAndroidStep6Description =>
      'Fabricantes de dispositivos costumam adicionar seus próprios controles de segundo plano:\n• Xiaomi/Redmi (MIUI/HyperOS): Configurações → Apps → Permissões → Início automático; permita o Stroom. Depois, abra Bateria → Economia de bateria de apps → Stroom → Sem restrições.\n• Huawei/Honor (EMUI/HarmonyOS): Configurações → Apps → Inicialização de apps → Stroom → Gerenciar manualmente; permita a inicialização automática, a inicialização secundária e a atividade em segundo plano.\n• OPPO/OnePlus/realme (ColorOS): Configurações → Bateria → Gerenciamento de bateria de apps → Stroom; permita atividade irrestrita em segundo plano.\n• vivo/iQOO (OriginOS): iManager → Gerenciamento de apps → Início automático; permita o Stroom.';

  @override
  String get platformTutorialAndroidStep7Title =>
      'Desativar a limpeza na tela de bloqueio e os modos de economia de energia';

  @override
  String get platformTutorialAndroidStep7Description =>
      'Abra Configurações → Bateria e desative “Economia de energia” ou “Economia de energia extrema”. Defina também “Limpar memória ao bloquear” como “Não limpar”. Os modos de economia de energia restringem a atividade em segundo plano e podem afetar a conclusão das tarefas.';

  @override
  String get platformTutorialIosStep1Title => 'Ativar Atualização em 2º Plano';

  @override
  String get platformTutorialIosStep1Description =>
      'Abra Ajustes → Geral → Atualização em 2º Plano, localize o Stroom e ative a opção. Escolha “Wi-Fi e Dados Celulares” para ter a melhor experiência.';

  @override
  String get platformTutorialIosStep2Title => 'Permitir notificações';

  @override
  String get platformTutorialIosStep2Description =>
      'Abra Ajustes → Notificações → Stroom e ative “Permitir notificações”. Ative os banners e a Central de Notificações para ver rapidamente as atualizações das tarefas.';

  @override
  String get platformTutorialIosStep3Title => 'Desativar o Modo Pouca Energia';

  @override
  String get platformTutorialIosStep3Description =>
      'Abra Ajustes → Bateria e desative o “Modo Pouca Energia”. Enquanto esse modo estiver ativado, o sistema restringe a atividade em segundo plano.';

  @override
  String get platformTutorialIosStep4Title =>
      'Entenda os limites de segundo plano do iOS';

  @override
  String get platformTutorialIosStep4Description =>
      'Versões anteriores ao iOS 26 não permitem que os apps permaneçam em segundo plano como no Android. O sistema concede aos apps breves períodos de execução somente em determinadas situações, como Atualização em 2º Plano, atualizações de localização ou reprodução de áudio, e pode suspender tarefas longas. Recomendamos:\n• Mantenha o Stroom em primeiro plano durante tarefas longas.\n• Volte ao app periodicamente para renovar o tempo em segundo plano.\n• Ative “Notificações de conclusão de tarefas” para tarefas importantes.';

  @override
  String get platformTutorialIosStep5Title =>
      'Dicas para manter tarefas em execução';

  @override
  String get platformTutorialIosStep5Description =>
      'O iOS 26 e versões posteriores aceitam tarefas persistentes em segundo plano. Em geral, elas continuam quando você troca de app ou bloqueia a tela, embora o sistema possa interrompê-las quando houver poucos recursos; o progresso aparece na tela bloqueada.\n\nVersões anteriores do iOS não aceitam tarefas persistentes em segundo plano. Volte ao app a cada poucos minutos (5–10 minutos é uma referência; o sistema decide o intervalo) para renovar o tempo em segundo plano e evitar a suspensão.\n\nEm todas as versões, não feche o Stroom deslizando-o para cima no seletor de apps; isso interrompe imediatamente todas as tarefas em execução.';

  @override
  String get platformTutorialIosStep6Title =>
      'Mantenha o app em primeiro plano';

  @override
  String get platformTutorialIosStep6Description =>
      'Em versões anteriores ao iOS 26, os apps têm tempo limitado em segundo plano. Para tarefas longas, mantenha o Stroom em primeiro plano ou volte a ele periodicamente para prolongar esse tempo.';

  @override
  String get platformTutorialWindowsStep1Title =>
      'Minimizar ao fechar a janela';

  @override
  String get platformTutorialWindowsStep1Description =>
      'Por padrão, clicar no botão de fechar minimiza o Stroom para a bandeja do sistema (perto do relógio), permitindo que ele continue em execução. Restaure-o pelo ícone da bandeja ou pelo menu “Mostrar janela principal”. Não saia enquanto houver tarefas em execução. Para sair, use “Sair do app completamente” na página “Otimização em segundo plano” ou escolha “Sair do Stroom” no menu da bandeja.';

  @override
  String get platformTutorialWindowsStep2Title =>
      'Desativar a Economia de bateria';

  @override
  String get platformTutorialWindowsStep2Description =>
      'Abra Configurações → Sistema → Energia e suspensão e desative a Economia de bateria. Outra opção é configurá-la para ser ativada somente quando a bateria ficar abaixo do nível escolhido.';

  @override
  String get platformTutorialWindowsStep3Title =>
      'Permitir apps em segundo plano';

  @override
  String get platformTutorialWindowsStep3Description =>
      'Abra Configurações → Privacidade e segurança → Apps em segundo plano, localize o Stroom e confira se ele está ativado. No Windows 11, acesse Configurações → Apps → Aplicativos instalados → Stroom → Opções avançadas → Permissões de aplicativos em segundo plano e escolha “Sempre”.';

  @override
  String get platformTutorialWindowsStep4Title =>
      'Desativar o modo de suspensão (opcional)';

  @override
  String get platformTutorialWindowsStep4Description =>
      'Para manter o Stroom em execução por períodos longos, abra Configurações → Sistema → Energia e defina “Suspender” como “Nunca” (somente quando conectado à tomada).';

  @override
  String get platformTutorialWindowsStep5Title =>
      'Adicionar o Stroom à inicialização';

  @override
  String get platformTutorialWindowsStep5Description =>
      'Abra o Gerenciador de Tarefas (Ctrl+Shift+Esc) → Inicializar, localize o Stroom e clique com o botão direito em “Ativar”. Ou abra Configurações → Apps → Inicialização e ative o Stroom.';

  @override
  String get platformTutorialMacosStep1Title => 'Minimizar ao fechar a janela';

  @override
  String get platformTutorialMacosStep1Description =>
      'Por padrão, fechar a janela mantém o Stroom em execução na barra de menus (no canto superior direito da tela). Clique no ícone dele na barra de menus ou escolha “Mostrar janela principal” para restaurá-lo. Não saia enquanto houver tarefas em execução. Para sair, use “Sair do app completamente” na página “Otimização em segundo plano” ou escolha “Sair do Stroom” no menu da barra de menus.';

  @override
  String get platformTutorialMacosStep2Title => 'Permitir notificações';

  @override
  String get platformTutorialMacosStep2Description =>
      'Abra Ajustes do Sistema → Notificações → Stroom e ative “Permitir notificações”. Recomendamos ativar os banners e a Central de Notificações.';

  @override
  String get platformTutorialMacosStep3Title =>
      'Desativar o Modo Pouca Energia (MacBook)';

  @override
  String get platformTutorialMacosStep3Description =>
      'Abra Ajustes do Sistema → Bateria → Adaptador de energia e desative o “Modo Pouca Energia”. Esse modo restringe a atividade em segundo plano.';

  @override
  String get platformTutorialMacosStep4Title => 'Manter o app ativo';

  @override
  String get platformTutorialMacosStep4Description =>
      'O macOS impõe poucas restrições a apps em segundo plano. Para tarefas longas, deixe a janela do Stroom aberta. Evite forçar o encerramento do app; basta fechar a janela.';

  @override
  String get platformTutorialMacosStep5Title =>
      'Abrir ao iniciar sessão (opcional)';

  @override
  String get platformTutorialMacosStep5Description =>
      'Abra Ajustes do Sistema → Geral → Itens de Início e adicione o Stroom para que ele seja iniciado automaticamente ao ligar o computador.';

  @override
  String get platformTutorialLinuxStep1Title => 'Minimizar ao fechar a janela';

  @override
  String get platformTutorialLinuxStep1Description =>
      'Por padrão, fechar a janela oculta o Stroom na bandeja do sistema (requer um ambiente de área de trabalho compatível com StatusNotifierItem e libayatana-appindicator3-dev durante a compilação). Restaure-o pelo menu da bandeja usando “Mostrar janela principal”. Não saia enquanto houver tarefas em execução. Para sair, use “Sair do app completamente” na página “Otimização em segundo plano” ou escolha “Sair do Stroom” no menu da bandeja.';

  @override
  String get platformTutorialLinuxStep2Title =>
      'Configurações do ambiente de área de trabalho';

  @override
  String get platformTutorialLinuxStep2Description =>
      'De acordo com seu ambiente de área de trabalho (GNOME, KDE, XFCE etc.), abra Configurações do sistema → Apps, localize o Stroom e confira se a atividade em segundo plano não está restrita.';

  @override
  String get platformTutorialLinuxStep3Title =>
      'Usar um serviço systemd (opcional)';

  @override
  String get platformTutorialLinuxStep3Description =>
      'Para tarefas longas em segundo plano, crie um serviço de usuário do systemd. Crie um arquivo stroom.service em ~/.config/systemd/user/ e defina ExecStart como o executável do Stroom.';

  @override
  String get platformTutorialLinuxStep4Title => 'Desativar a suspensão';

  @override
  String get platformTutorialLinuxStep4Description =>
      'Para um servidor ou computador que precisa funcionar por muito tempo, defina HandleLidSwitch=ignore em /etc/systemd/logind.conf para impedir a suspensão quando a tampa for fechada.';

  @override
  String get platformTutorialLinuxStep5Title =>
      'Ativar a inicialização automática';

  @override
  String get platformTutorialLinuxStep5Description =>
      'No GNOME, use Ajustes → Aplicativos de inicialização → Adicionar Stroom. Ou crie um arquivo stroom.desktop em ~/.config/autostart/.';

  @override
  String get platformTutorialWebStep1Title => 'Mantenha a aba aberta';

  @override
  String get platformTutorialWebStep1Description =>
      'Os navegadores da web não aceitam serviços em segundo plano. Mantenha a aba do Stroom aberta enquanto as tarefas estiverem em execução; fechar a aba ou atualizar a página interrompe-as imediatamente.';

  @override
  String get platformTutorialWebStep2Title =>
      'Impedir a suspensão da aba pelo navegador';

  @override
  String get platformTutorialWebStep2Description =>
      'Os navegadores podem congelar abas inativas em segundo plano para economizar recursos. Mantenha a aba do Stroom em primeiro plano enquanto as tarefas estiverem em execução ou interaja periodicamente com a página para mantê-la ativa.';

